<section class="admin-card"><div class="card-head"><form class="admin-search admin-filter" method="get"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?=e($search)?>" placeholder="Reference, customer, company or product"><select name="status"><option value="">All statuses</option><?php foreach($statuses as $status):?><option value="<?=e($status)?>" <?=$filterStatus===$status?'selected':''?>><?=e(str_replace('_',' ',$status))?></option><?php endforeach;?></select><button>Filter</button></form></div><div class="table-responsive"><table class="admin-table"><thead><tr><th>Reference</th><th>Customer</th><th>Contact</th><th>Requirement</th><th>Status</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($rfqs as $rfq):?><tr class="<?=$rfq['is_read']?'':'unread'?>"><td><a href="<?=e(url('admin/enquiries/'.$rfq['id']))?>"><strong><?=e($rfq['reference'])?></strong></a><?=$rfq['is_read']?'':'<span class="new-dot">New</span>'?></td><td><?=e($rfq['full_name'])?><small><?=e($rfq['company_name'])?></small></td><td><?=e($rfq['phone'])?><small><?=e($rfq['email'])?></small></td><td><?=e($rfq['product_name']?:'General')?><small><?=e($rfq['quantity_requirement']??'')?></small></td><td><span class="status status-<?=strtolower($rfq['status'])?>"><?=e(str_replace('_',' ',$rfq['status']))?></span></td><td><?=e(date('d M Y, h:i A',strtotime($rfq['created_at'])))?></td><td><a class="icon-link" href="<?=e(url('admin/enquiries/'.$rfq['id']))?>"><i class="fa-solid fa-chevron-right"></i></a></td></tr><?php endforeach;?><?php if(!$rfqs):?><tr><td colspan="7" class="empty-cell">No quote requests found.</td></tr><?php endif;?></tbody></table></div></section>

